<script>
(function(){
'use strict';
const S={scope:'mine',search:'',conversation:null,lastId:0,quote:null,autoSync:false,autoFallback:false,recorder:null,recordStream:null,audioChunks:[],recordBlob:null,recordUrl:null,recordStartedAt:0,recordElapsed:0,recordTimer:null,pendingFile:null,pendingUrl:null,pendingPtt:false,messageMap:{},messages:[],openAbort:null,messageSearchResults:[],messageSearchIndex:-1,messageSearchTimer:null,mediaObjects:new Set(),csrfName:<?php echo json_encode($csrf_name); ?>,csrf:<?php echo json_encode($csrf_hash); ?>,poll:<?php echo (int)$poll_interval*1000; ?>,realtimePoll:<?php echo (int)$realtime_poll_ms; ?>,apiSync:<?php echo (int)$api_sync_interval*1000; ?>,currentStaff:<?php echo (int)$current_staff_id; ?>,canViewAll:<?php echo $can_view_all?'true':'false'; ?>,initialConversation:<?php echo (int)$initial_conversation_id; ?>,installPrompt:null,listSignature:'',listBusy:false,pollBusy:false,openSeq:0,lastListAt:0,lastApiSyncAt:0,apiSyncBusy:false,eventCursor:0,eventBusy:false,listDirty:false,pollDirty:false,watchdogBusy:false};
const U={conversations:<?php echo json_encode(admin_url('connect_api_chat/conversations')); ?>,messages:<?php echo json_encode(admin_url('connect_api_chat/messages')); ?>,poll:<?php echo json_encode(admin_url('connect_api_chat/poll')); ?>,events:<?php echo json_encode(admin_url('connect_api_chat/realtime_events')); ?>,sync:<?php echo json_encode(admin_url('connect_api_chat/sync')); ?>,syncConversation:<?php echo json_encode(admin_url('connect_api_chat/sync_conversation')); ?>,sendText:<?php echo json_encode(admin_url('connect_api_chat/send_text')); ?>,sendMedia:<?php echo json_encode(admin_url('connect_api_chat/send_media')); ?>,newChat:<?php echo json_encode(admin_url('connect_api_chat/new_chat')); ?>,assign:<?php echo json_encode(admin_url('connect_api_chat/assign')); ?>,deleteMessage:<?php echo json_encode(admin_url('connect_api_chat/delete_message')); ?>,switchInstance:<?php echo json_encode(admin_url('connect_api_chat/switch_instance')); ?>,sendContact:<?php echo json_encode(admin_url('connect_api_chat/send_contact')); ?>,searchMessages:<?php echo json_encode(admin_url('connect_api_chat/search_messages')); ?>,conversationStatus:<?php echo json_encode(admin_url('connect_api_chat/conversation_status')); ?>,watchdog:<?php echo json_encode(admin_url('connect_api_chat/inbound_watchdog')); ?>};
const $=id=>document.getElementById(id); const q=(s,c=document)=>c.querySelector(s); const qa=(s,c=document)=>Array.from(c.querySelectorAll(s));
function esc(v){return String(v==null?'':v).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[m]));}
function toast(msg,ms=2600){const e=$('cacToast');if(!e)return;e.textContent=msg;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),ms);}
function updateCsrf(r){if(r&&r.csrf_hash)S.csrf=r.csrf_hash;}
async function request(url,opts={}){opts.credentials='same-origin';opts.headers=Object.assign({'X-Requested-With':'XMLHttpRequest'},opts.headers||{});const r=await fetch(url,opts);let data={};try{data=await r.json();}catch(e){data={success:false,message:'Resposta inválida do servidor (HTTP '+r.status+').'};}updateCsrf(data);if(!r.ok||data.success===false)throw new Error(data.message||('HTTP '+r.status));return data;}
function formBody(obj){const fd=new FormData();Object.keys(obj||{}).forEach(k=>fd.append(k,obj[k]==null?'':obj[k]));fd.append(S.csrfName,S.csrf);return fd;}
function formatTime(v){if(!v)return'';let d=new Date(String(v).replace(' ','T'));if(isNaN(d))return'';return d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}
function formatDay(ts){const d=new Date((parseInt(ts)||0)*1000);if(isNaN(d))return'';const today=new Date();if(d.toDateString()===today.toDateString())return'Hoje';return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});}
function initials(name){const p=String(name||'?').trim().split(/\s+/);return ((p[0]||'?')[0]+(p.length>1?p[p.length-1][0]:'')).toUpperCase();}
function avatarHtml(name,url){return url?'<img src="'+esc(url)+'" alt="">':esc(initials(name));}
function setScope(scope){S.scope=scope;S.listSignature='';qa('.cac-tab').forEach(b=>b.classList.toggle('active',b.dataset.scope===scope));loadList(false,true);}
function updateTabCounts(counts){counts=counts||{};qa('.cac-tab-count').forEach(el=>{const n=parseInt(counts[el.dataset.count]||0)||0;el.textContent=n>99?'99+':String(n);el.classList.toggle('has',n>0);});}
async function loadList(allowAuto=true,showLoading=false){if(S.listBusy){S.listDirty=true;return null;}S.listBusy=true;const list=$('cacList');const hadRows=!!q('.cac-conv',list);if(showLoading&&!hadRows)list.innerHTML='<div class="cac-list-state">Carregando...</div>';let rows=[];try{const url=U.conversations+'?scope='+encodeURIComponent(S.scope)+'&search='+encodeURIComponent(S.search);const r=await request(url);S.lastListAt=Date.now();rows=r.conversations||[];updateTabCounts(r.counts||{});renderList(rows);if(!rows.length&&allowAuto&&S.scope==='mine'&&!S.autoFallback){S.autoFallback=true;S.scope='unassigned';qa('.cac-tab').forEach(b=>b.classList.toggle('active',b.dataset.scope===S.scope));S.listSignature='';S.listBusy=false;return await loadList(false,false);}return rows;}catch(e){if(!hadRows)showListError(e.message);return null;}finally{S.listBusy=false;if(S.listDirty){S.listDirty=false;setTimeout(()=>loadList(false,false),0);}}}
function showListError(msg){$('cacList').innerHTML='<div class="cac-list-state"><strong><?php echo addslashes(_l('connect_api_chat_connection_error')); ?></strong><br><span>'+esc(msg)+'</span><br><button class="cac-btn" id="cacRetry" style="margin-top:10px"><?php echo addslashes(_l('connect_api_chat_retry')); ?></button></div>';const b=$('cacRetry');if(b)b.onclick=()=>loadList(true,true);}
function renderList(rows){const signature=JSON.stringify((rows||[]).map(c=>[c.id,c.display_name,c.title,c.profile_pic_url,c.last_message_preview,c.last_message_at,c.unread_count,c.assigned_staff_id,c.status,c.current_ticket_number,c.new_ticket_flag]));if(signature===S.listSignature){qa('.cac-conv',$('cacList')).forEach(el=>el.classList.toggle('active',!!S.conversation&&String(S.conversation.id)===String(el.dataset.id)));return;}S.listSignature=signature;const list=$('cacList'),scroll=list.scrollTop;let h='';rows.forEach(c=>{const name=c.display_name||c.title||c.phone_number||'Contato WhatsApp';const ticket=c.current_ticket_number?'<span class="cac-ticket-badge '+(parseInt(c.new_ticket_flag||0)===1?'new':'')+'">'+(parseInt(c.new_ticket_flag||0)===1?'NOVO · ':'')+'#'+parseInt(c.current_ticket_number)+'</span>':'';h+='<div class="cac-conv '+(S.conversation&&String(S.conversation.id)===String(c.id)?'active':'')+'" data-id="'+c.id+'"><div class="cac-avatar">'+avatarHtml(name,c.profile_pic_url)+'</div><div class="cac-conv-body"><div class="cac-conv-top"><span class="cac-conv-name">'+esc(name)+ticket+'</span><span class="cac-conv-time">'+formatTime(c.last_message_at)+'</span></div><div class="cac-conv-bottom"><span class="cac-conv-preview">'+esc(c.last_message_preview||'')+'</span>'+(parseInt(c.unread_count)>0?'<span class="cac-unread">'+parseInt(c.unread_count)+'</span>':'')+'</div><div class="cac-assignee">'+esc(c.assigned_name||'<?php echo addslashes(_l('connect_api_chat_not_assigned')); ?>')+'</div></div></div>';});list.innerHTML=h||'<div class="cac-list-state"><?php echo addslashes(_l('connect_api_chat_no_conversations')); ?></div>';list.scrollTop=scroll;qa('.cac-conv',list).forEach(el=>el.onclick=()=>openChat(parseInt(el.dataset.id)));}
async function openChat(id,focusId=0){
    const seq=++S.openSeq;
    if(S.openAbort)S.openAbort.abort();
    releaseMediaObjects();
    S.openAbort=new AbortController();
    qa('.cac-conv',$('cacList')).forEach(el=>el.classList.toggle('active',String(el.dataset.id)===String(id)));
    const selected=q('.cac-conv[data-id="'+id+'"]',$('cacList')); if(selected){const badge=q('.cac-unread',selected);if(badge)badge.remove();}
    try{
        let url=U.messages+'?conversation_id='+id;if(focusId)url+='&focus_id='+encodeURIComponent(focusId);
        const r=await request(url,{signal:S.openAbort.signal});
        if(seq!==S.openSeq)return;
        S.conversation=r.conversation;S.lastId=0;S.messageMap={};
        $('cacShell').classList.add('chat-open');$('cacChatHead').style.visibility='visible';
        const name=r.conversation.display_name||r.conversation.title||r.conversation.phone_number||'Contato WhatsApp';
        updateActiveConversationMeta(r.conversation);$('cacActiveAvatar').innerHTML=avatarHtml(name,r.conversation.profile_pic_url);
        $('cacDetailAvatar').innerHTML=avatarHtml(name,r.conversation.profile_pic_url);
        updateConversationState(r.conversation);
        <?php if($can_assign){ ?>$('cacAssignee').value=r.conversation.assigned_staff_id||0;$('cacClaim').style.display=r.conversation.assigned_staff_id?'none':'inline-block';<?php } ?>
        renderCrm(r.crm);renderHistory(r.assignment_history);S.messages=sortMessages(r.messages||[]);renderMessages(S.messages);
        if(focusId){setTimeout(()=>{const hit=q('.cac-msg-row[data-id="'+focusId+'"]',$('cacMessages'));if(hit){hit.classList.add('cac-search-hit');hit.scrollIntoView({block:'center',behavior:'smooth'});setTimeout(()=>hit.classList.remove('cac-search-hit'),1800);}},60);}
    }catch(e){if(e&&e.name==='AbortError')return;if(seq===S.openSeq)toast(e.message,4000);}
}
function updateConversationState(c){
    const closed=(c&&String(c.status||'open')==='closed');
    const bar=$('cacClosedBar');if(bar)bar.classList.toggle('open',closed);
    <?php if($can_send){ ?>const composer=$('cacComposer');if(composer){composer.style.display=closed?'none':'block';if(!closed)resizeComposer();}<?php } ?>
    <?php if($can_close){ ?>
    const top=$('cacStatusToggle');if(top){top.textContent=closed?'↻':'✓';top.title=closed?'<?php echo addslashes(_l('connect_api_chat_reopen_conversation')); ?>':'<?php echo addslashes(_l('connect_api_chat_close_conversation')); ?>';}
    const db=$('cacDetailStatusBtn');if(db){db.textContent=closed?'<?php echo addslashes(_l('connect_api_chat_reopen_conversation')); ?>':'<?php echo addslashes(_l('connect_api_chat_close_conversation')); ?>';db.classList.toggle('danger',!closed);db.classList.toggle('primary',closed);}
    const dt=$('cacDetailStatusText');if(dt)dt.textContent=(closed?'Encerrado':'Aberto')+(c&&c.current_ticket_number?' · Atendimento #'+c.current_ticket_number:'');
    <?php } ?>
}
function renderCrm(crm){let h='';if(crm&&crm.contact)h+='<div class="cac-crm">👤 <a target="_blank" href="'+esc(crm.contact.url)+'">'+esc(crm.contact.name)+'</a><div>'+esc(crm.contact.company||'Cliente')+'</div></div>';if(crm&&crm.lead)h+='<div class="cac-crm">◎ <a target="_blank" href="'+esc(crm.lead.url)+'">'+esc(crm.lead.name)+'</a><div>Lead #'+crm.lead.id+'</div></div>';$('cacCrm').innerHTML=h||'<span style="color:var(--cac-muted);font-size:12px"><?php echo addslashes(_l('connect_api_chat_no_crm_context')); ?></span>';}
function renderHistory(rows){let h='';(rows||[]).forEach(x=>{const action=x.action||'assigned',who=x.actor_name||'Sistema',target=x.to_name||'Não atribuído',tn=x.ticket_number?(' #'+x.ticket_number):'';let label='Atribuído a '+target;if(action==='transferred')label='Transferido para '+target;else if(action==='claimed')label='Assumido por '+target;else if(action==='unassigned')label='Liberado';else if(action==='closed')label='Atendimento'+tn+' encerrado';else if(action==='reopened')label='Atendimento'+tn+' reaberto';else if(action==='new_ticket')label='Novo atendimento'+tn+' iniciado';h+='<div class="cac-history-item"><strong>'+esc(label)+'</strong>'+esc(who)+(x.created_at?' · '+esc(x.created_at):'')+'</div>';});$('cacHistory').innerHTML=h||'<span style="color:var(--cac-muted);font-size:12px"><?php echo addslashes(_l('connect_api_chat_no_assignment_history')); ?></span>'; }
function sortMessages(rows){return (rows||[]).slice().sort((a,b)=>{const ta=parseInt(a.message_timestamp)||0,tb=parseInt(b.message_timestamp)||0;if(ta!==tb)return ta-tb;return (parseInt(a.id)||0)-(parseInt(b.id)||0);});}
function messageKey(m){return m&&m.api_message_id?('api:'+m.api_message_id):('id:'+String(m&&m.id||''));}
function mergeMessages(base,extra){const map=new Map();(base||[]).forEach(m=>map.set(messageKey(m),m));(extra||[]).forEach(m=>{const k=messageKey(m);map.set(k,Object.assign({},map.get(k)||{},m));});return sortMessages(Array.from(map.values()));}
function renderMessages(rows){
    const box=$('cacMessages');box.innerHTML='';S.messageMap={};
    rows=sortMessages(rows||[]);S.messages=rows;
    rows.forEach(m=>{if(m.api_message_id)S.messageMap[m.api_message_id]=m;});
    if(!rows.length){box.innerHTML='<div class="cac-empty"><div class="cac-empty-card"><p><?php echo addslashes(_l('connect_api_chat_no_messages')); ?></p></div></div>';return;}
    let day='';const seenTickets=new Set();rows.forEach(m=>{const d=formatDay(m.message_timestamp);if(d!==day){day=d;box.insertAdjacentHTML('beforeend','<div class="cac-day"><span>'+esc(day)+'</span></div>');}const tn=parseInt(m.ticket_number||0)||0;if(tn&&!seenTickets.has(tn)){seenTickets.add(tn);box.insertAdjacentHTML('beforeend','<div class="cac-ticket-separator"><span>Atendimento #'+tn+(m.ticket_status==='closed'?' · encerrado':'')+'</span></div>');}appendMessage(m,false);});scrollBottom();
}
function messageLabel(m){const type=m.message_type||'text';if(m.text_content)return m.text_content;if(m.caption)return m.caption;if(type==='audio')return'Áudio';if(type==='image')return'Foto';if(type==='video')return'Vídeo';if(type==='document')return m.file_name||'Documento';if(type==='contact')return'Contato';return'['+type+']';}
function textHtml(value){let s=esc(value||'').replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>');s=s.replace(/\*([^*\n]+)\*/g,'<strong>$1</strong>').replace(/_([^_\n]+)_/g,'<em>$1</em>').replace(/~([^~\n]+)~/g,'<del>$1</del>');return s.replace(/\n/g,'<br>');}
function fmtDuration(sec){sec=parseInt(sec)||0;return String(Math.floor(sec/60))+':'+String(sec%60).padStart(2,'0');}
function waveformHtml(b64){try{if(!b64)return'';const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));if(!bytes.length)return'';const max=34,n=Math.min(46,bytes.length),step=Math.max(1,Math.floor(bytes.length/n));let out='';for(let i=0;i<bytes.length&&out.split('<i').length<=47;i+=step){const h=3+Math.round((bytes[i]/255)*23);out+='<i style="height:'+h+'px"></i>';}return out;}catch(e){return'';}}

function quoteMessage(m){if(!m||!m.api_message_id)return;S.quote={id:m.api_message_id,text:messageLabel(m),sender:parseInt(m.from_me)===1?(m.staff_name||'Você'):(m.sender_name||S.conversation?.display_name||'Contato')};$('cacQuoteName').textContent='Responder a '+S.quote.sender;$('cacQuoteText').textContent=S.quote.text;$('cacQuote').style.display='block';$('cacMessage').focus();}
function appendMessage(m,scroll=true){
    S.lastId=Math.max(S.lastId,parseInt(m.id)||0);if(m.api_message_id)S.messageMap[m.api_message_id]=m;
    const mine=parseInt(m.from_me)===1,type=m.message_type||'text';
    let text=m.is_deleted==1?'<?php echo addslashes(_l('connect_api_chat_deleted')); ?>':(m.text_content||m.caption||'');
    let quotedHtml='';if(m.quoted_api_message_id){const qm=S.messageMap[m.quoted_api_message_id];quotedHtml='<div class="cac-quoted-block"><strong>'+esc(qm?(parseInt(qm.from_me)===1?(qm.staff_name||'Você'):(qm.sender_name||'Contato')):'Mensagem respondida')+'</strong>'+esc(qm?messageLabel(qm):'Mensagem original')+'</div>';}
    let media='';
    if(type==='contact'){media='<div class="cac-contact-card"><div class="cac-contact-icon">👤</div><div class="cac-contact-text">'+esc(text||'Contato compartilhado')+'</div></div>';text='';}
    else if(m.media_url){
        const src=esc(m.media_url),lazy=parseInt(m.media_lazy||0)===1,cached=parseInt(m.media_cached||0)===1,thumb=m.thumbnail_base64||'';
        if(type==='document')media='<div class="cac-media"><a class="cac-file-link" target="_blank" href="'+esc(m.media_download_url||m.media_url)+'">📄 '+esc(m.file_name||'Arquivo')+'</a></div>';
        else if(cached){
            if(type==='image'||type==='sticker')media='<div class="cac-media"><a target="_blank" href="'+src+'"><img src="'+src+'" alt="Imagem"></a></div>';
            else if(type==='video')media='<div class="cac-media"><video controls preload="metadata" src="'+src+'"></video></div>';
            else if(type==='audio')media='<div class="cac-media"><audio controls preload="metadata" src="'+src+'"></audio></div>';
        }else if((type==='image'||type==='video'||type==='sticker')&&thumb){
            const label=type==='video'?'▶ Carregar vídeo':'🔍 Carregar imagem';
            media='<div class="cac-media"><div class="cac-media-placeholder cac-thumb-wrap" data-media-type="'+esc(type)+'" data-media-url="'+src+'"><img alt="Prévia" src="data:image/jpeg;base64,'+esc(thumb)+'"><div class="cac-thumb-overlay"><button type="button" class="cac-media-load cac-thumb-action">'+label+'</button></div><div class="cac-media-placeholder-error"></div></div></div>';
        }else if(type==='audio'){
            media='<div class="cac-media"><div class="cac-media-placeholder cac-audio-lazy" data-media-type="audio" data-media-url="'+src+'"><button type="button" class="cac-media-load" title="Carregar áudio">▶</button><div class="cac-wave">'+waveformHtml(m.media_waveform||'')+'</div><span class="cac-media-duration">'+fmtDuration(m.media_duration||0)+'</span><div class="cac-media-placeholder-error"></div></div></div>';
        }else{
            const icon=(type==='video'?'🎬':'🖼️'),title=(type==='video'?'Vídeo':'Imagem');
            media='<div class="cac-media"><div class="cac-media-placeholder" data-media-type="'+esc(type)+'" data-media-url="'+src+'"><div class="cac-media-placeholder-icon">'+icon+'</div><div class="cac-media-placeholder-body"><div class="cac-media-placeholder-title">'+title+'</div><div class="cac-media-placeholder-note"><?php echo addslashes(_l('connect_api_chat_media_not_downloaded')); ?></div><button type="button" class="cac-media-load"><?php echo addslashes(_l('connect_api_chat_media_load')); ?></button><div class="cac-media-placeholder-error"></div></div></div></div>';
        }
    }
    if(!text&&media==='')text=messageLabel(m);
    const row=document.createElement('div');row.className='cac-msg-row'+(mine?' mine':'');row.dataset.id=m.id;
    row.innerHTML='<div class="cac-bubble">'+quotedHtml+(mine&&m.staff_name?'<div class="cac-sender"><?php echo addslashes(_l('connect_api_chat_internal_sender')); ?> '+esc(m.staff_name)+'</div>':'')+(text?'<div class="cac-text">'+textHtml(text)+'</div>':'')+media+'<button type="button" class="cac-reply-action" title="Responder">↩</button><div class="cac-msg-meta"><span>'+new Date((parseInt(m.message_timestamp)||0)*1000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+'</span>'+(mine&&<?php echo $can_delete?'true':'false'; ?>&&m.api_message_id?'<button class="cac-delete" data-api="'+esc(m.api_message_id)+'" title="Excluir">⌫</button>':'')+'</div></div>';
    const reply=q('.cac-reply-action',row);if(reply)reply.onclick=e=>{e.stopPropagation();quoteMessage(m);};row.ondblclick=()=>quoteMessage(m);
    const mediaLoad=q('.cac-media-load',row);if(mediaLoad)mediaLoad.onclick=e=>{e.stopPropagation();loadLazyMedia(mediaLoad,m);};
    $('cacMessages').appendChild(row);if(scroll)scrollBottom();
}
function releaseMediaObjects(){if(!S.mediaObjects)return;S.mediaObjects.forEach(u=>{try{URL.revokeObjectURL(u);}catch(e){}});S.mediaObjects.clear();}
async function mountMediaHolder(holder,m){if(!holder||holder.dataset.loading==='1')return;holder.dataset.loading='1';holder.classList.add('loading');const button=q('.cac-media-load',holder),note=q('.cac-media-placeholder-note',holder),err=q('.cac-media-placeholder-error',holder);if(button){button.disabled=true;button.textContent='Carregando...';}if(note)note.textContent='Carregando mídia...';if(err)err.textContent='';const raw=holder.dataset.mediaUrl||m.media_url||'';const src=raw+(raw.includes('?')?'&':'?')+'manual=1';const type=holder.dataset.mediaType||m.message_type||'document';try{let replacement;if(type==='image'||type==='sticker'){const a=document.createElement('a');a.className='cac-image-link';a.target='_blank';a.href=src;const img=document.createElement('img');img.alt='Imagem';img.loading='eager';img.src=src;img.onerror=()=>mediaElementFailed(holder,replacement,'Não foi possível carregar a imagem.');a.appendChild(img);replacement=a;}else if(type==='video'){const v=document.createElement('video');v.controls=true;v.preload='metadata';v.src=src;v.onerror=()=>mediaElementFailed(holder,replacement,'Não foi possível carregar o vídeo.');replacement=v;}else if(type==='audio'){const wrap=document.createElement('div');wrap.className='cac-audio-card';const a=document.createElement('audio');a.controls=true;a.preload='metadata';a.src=src;a.onerror=()=>mediaElementFailed(holder,replacement,'Não foi possível carregar o áudio.');wrap.appendChild(a);replacement=wrap;}if(!replacement)throw new Error('Tipo de mídia não suportado.');holder.replaceWith(replacement);}catch(e){holder.dataset.loading='0';holder.classList.remove('loading');holder.classList.add('error');if(note)note.textContent='Não foi possível carregar a mídia.';if(err)err.textContent=e.message||'Falha desconhecida';if(button){button.style.display='inline-block';button.disabled=false;button.textContent='<?php echo addslashes(_l('connect_api_chat_media_retry')); ?>';}}}
function mediaElementFailed(original,replacement,message){if(!replacement||!replacement.parentNode)return;original.dataset.loading='0';original.classList.remove('loading');original.classList.add('error');const note=q('.cac-media-placeholder-note',original),err=q('.cac-media-placeholder-error',original),button=q('.cac-media-load',original);if(note)note.textContent='Não foi possível carregar a mídia.';if(err)err.textContent=message||'Falha ao obter a mídia.';if(button){button.style.display='inline-block';button.disabled=false;button.textContent='<?php echo addslashes(_l('connect_api_chat_media_retry')); ?>';}replacement.replaceWith(original);}
function loadLazyMedia(button,m){const holder=button.closest('.cac-media-placeholder');if(holder)mountMediaHolder(holder,m);}
function scrollBottom(){const e=$('cacMessages');e.scrollTop=e.scrollHeight;}
function resizeComposer(){const input=$('cacMessage');if(!input)return;input.style.height='auto';input.style.height=Math.min(168,Math.max(44,input.scrollHeight))+'px';}
function setComposeStatus(text){const status=$('cacComposeStatus');if(!status)return;if(!text){status.style.display='none';status.textContent='';return;}status.textContent=text;status.style.display='block';}
async function sendText(){
    if(!S.conversation)return;if(S.pendingFile)return sendPendingFile();
    const input=$('cacMessage'),text=input.value.trim();if(!text)return;const btn=$('cacSend');btn.disabled=true;setComposeStatus('Enviando...');
    try{await request(U.sendText,{method:'POST',body:formBody({conversation_id:S.conversation.id,message:text,quoted_id:S.quote?S.quote.id:''})});input.value='';resizeComposer();cancelQuote();await poll();S.listSignature='';setComposeStatus('Enviado');setTimeout(()=>setComposeStatus(''),900);}catch(e){setComposeStatus('Falha no envio');toast(e.message,5000);}finally{btn.disabled=false;input.focus();}
}
async function poll(){if(!S.conversation)return;if(S.pollBusy){S.pollDirty=true;return;}S.pollBusy=true;try{const currentId=S.conversation.id;const r=await request(U.poll+'?conversation_id='+currentId+'&after_id='+S.lastId);if(r.conversation&&String(r.conversation.id)===String(currentId)){const oldTicket=S.conversation.current_ticket_id,oldStatus=S.conversation.status;S.conversation=Object.assign({},S.conversation,r.conversation);updateActiveConversationMeta(S.conversation);updateConversationState(S.conversation);if(String(oldTicket)!==String(S.conversation.current_ticket_id)||String(oldStatus)!==String(S.conversation.status))S.listSignature='';}if(r.messages&&r.messages.length){S.messages=mergeMessages(S.messages,r.messages);renderMessages(S.messages);S.listSignature='';}}catch(e){}finally{S.pollBusy=false;if(S.pollDirty){S.pollDirty=false;setTimeout(()=>poll(),0);}}}
async function inboundWatchdog(){if(S.watchdogBusy||document.hidden)return;S.watchdogBusy=true;try{const r=await request(U.watchdog);if(parseInt(r.recovered||0)>0){S.listSignature='';await loadList(false,false);if(S.conversation)await poll();toast('Mensagem recebida recuperada pelo watchdog',2600);}}catch(e){}finally{S.watchdogBusy=false;}}
async function pollRealtime(){if(S.eventBusy||document.hidden)return;S.eventBusy=true;try{const r=await request(U.events+'?after='+encodeURIComponent(S.eventCursor||0));const previous=S.eventCursor||0;S.eventCursor=parseInt(r.cursor||S.eventCursor||0)||0;if(!previous)return;const events=r.events||[];if(!events.length)return;let activeChanged=false,newTicket=null;events.forEach(ev=>{if(ev.event_type==='ticket.new')newTicket=ev;if(S.conversation&&String(ev.conversation_id||'')===String(S.conversation.id))activeChanged=true;});if(activeChanged)await poll();if(newTicket){if(S.scope==='mine'||(S.conversation&&String(newTicket.conversation_id||'')===String(S.conversation.id))){S.scope='unassigned';qa('.cac-tab').forEach(b=>b.classList.toggle('active',b.dataset.scope===S.scope));}toast(S.conversation&&String(newTicket.conversation_id||'')===String(S.conversation.id)?('Novo atendimento recebido · #'+(S.conversation.current_ticket_number||'')):'Novo atendimento recebido',3200);}S.listSignature='';await loadList(false,false);}catch(e){}finally{S.eventBusy=false;}}
function updateActiveConversationMeta(c){if(!c)return;const name=c.display_name||c.title||c.phone_number||'Contato WhatsApp';const phone=c.phone_number||((c.remote_jid||'').includes('@lid')?'WhatsApp LID':c.remote_jid);$('cacActiveName').textContent=name;$('cacActiveSub').textContent=phone+(c.current_ticket_number?' · Atendimento #'+c.current_ticket_number:'');$('cacDetailName').textContent=name;$('cacDetailPhone').textContent=phone;}
function cancelQuote(){S.quote=null;$('cacQuote').style.display='none';$('cacQuoteText').textContent='';$('cacQuoteName').textContent='Responder';}
function closePopovers(){['cacAttachMenu','cacEmojiPanel'].forEach(id=>$(id)&&$(id).classList.remove('open'));}
function fileSize(size){size=parseInt(size)||0;if(size<1024)return size+' B';if(size<1024*1024)return(size/1024).toFixed(1)+' KB';return(size/1024/1024).toFixed(1)+' MB';}
function clearPending(){if(S.pendingUrl)URL.revokeObjectURL(S.pendingUrl);S.pendingUrl=null;S.pendingFile=null;S.pendingPtt=false;$('cacPending').classList.remove('open');$('cacPendingPreview').innerHTML='📎';$('cacPendingName').textContent='';$('cacPendingMeta').textContent='';const a=$('cacPendingAudio');a.pause();a.removeAttribute('src');a.style.display='none';}
function setPendingFile(file,ptt=false){if(!file)return;clearPending();S.pendingFile=file;S.pendingPtt=!!ptt;const type=file.type||'';$('cacPendingName').textContent=file.name||'Arquivo';$('cacPendingMeta').textContent=(type||'arquivo')+' · '+fileSize(file.size);const preview=$('cacPendingPreview');
    if(type.startsWith('image/')){S.pendingUrl=URL.createObjectURL(file);preview.innerHTML='<img src="'+esc(S.pendingUrl)+'" alt="">';}
    else if(type.startsWith('video/')){S.pendingUrl=URL.createObjectURL(file);preview.innerHTML='<video muted src="'+esc(S.pendingUrl)+'"></video>';}
    else if(type.startsWith('audio/')){S.pendingUrl=URL.createObjectURL(file);preview.textContent='🎧';const a=$('cacPendingAudio');a.src=S.pendingUrl;a.style.display='block';}
    else preview.textContent='📄';$('cacPending').classList.add('open');$('cacMessage').focus();
}
async function sendFile(file,ptt=false,caption=''){if(!S.conversation||!file)return false;const fd=new FormData();fd.append('file',file,file.name||('audio-'+Date.now()+'.webm'));fd.append('conversation_id',S.conversation.id);fd.append('caption',caption||'');fd.append('quoted_id',S.quote?S.quote.id:'');if(ptt)fd.append('ptt','1');fd.append(S.csrfName,S.csrf);setComposeStatus('Enviando arquivo...');try{await request(U.sendMedia,{method:'POST',body:fd});cancelQuote();await poll();S.listSignature='';setComposeStatus('Enviado');setTimeout(()=>setComposeStatus(''),900);return true;}catch(e){setComposeStatus('Falha no envio');toast(e.message,5000);return false;}}
async function sendPendingFile(){if(!S.pendingFile)return;const file=S.pendingFile,ptt=S.pendingPtt,caption=ptt?'':$('cacMessage').value.trim();$('cacSend').disabled=true;try{if(await sendFile(file,ptt,caption)){clearPending();$('cacMessage').value='';resizeComposer();}}finally{$('cacSend').disabled=false;}}
function insertEmoji(emoji){const input=$('cacMessage'),start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+emoji+input.value.slice(end);const pos=start+emoji.length;input.setSelectionRange(pos,pos);input.dispatchEvent(new Event('input'));input.focus();}
const EMOJIS={faces:['😀','😃','😄','😁','😆','😅','😂','🤣','😊','😇','🙂','🙃','😉','😍','🥰','😘','😋','😎','🤩','🥳','😏','😢','😭','😡','🤔','🤗','🫡','😴','🤯','🥺','😬','🤭'],gestures:['👍','👎','👌','✌️','🤞','🤟','🤘','👏','🙌','👐','🤲','🙏','💪','👊','🤝','🫶','👋','☝️','👇','👉','👈','✍️','🤳','💅'],symbols:['❤️','🩷','🧡','💛','💚','💙','💜','🖤','🤍','🤎','💔','❣️','💕','💞','💓','💗','💖','💘','💝','💟','✅','❌','⚠️','🎉','🎂','🔥','⭐','✨','💯','🚀','📌','📎']};
function renderEmoji(cat='faces'){const grid=$('cacEmojiGrid');grid.innerHTML=(EMOJIS[cat]||EMOJIS.faces).map(e=>'<button type="button" class="cac-emoji-item" data-emoji="'+esc(e)+'">'+e+'</button>').join('');qa('.cac-emoji-item',grid).forEach(b=>b.onclick=()=>insertEmoji(b.dataset.emoji));qa('.cac-emoji-tab').forEach(b=>b.classList.toggle('active',b.dataset.emojiCat===cat));}
function formatRecTime(sec){sec=Math.max(0,Math.floor(sec));return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function recElapsed(){if(!S.recordStartedAt)return S.recordElapsed||0;return S.recordElapsed+(Date.now()-S.recordStartedAt)/1000;}
function updateRecTimer(){if($('cacRecTime'))$('cacRecTime').textContent=formatRecTime(recElapsed());}
function recorderMime(){const prefs=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/webm','audio/mp4'];for(const m of prefs){if(window.MediaRecorder&&MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(m))return m;}return'';}
function showRecorder(){closePopovers();$('cacComposeRow').style.display='none';$('cacRecorder').classList.add('open');}
function resetRecorder(){if(S.recordTimer){clearInterval(S.recordTimer);S.recordTimer=null;}if(S.recordStream){S.recordStream.getTracks().forEach(t=>t.stop());S.recordStream=null;}if(S.recordUrl){URL.revokeObjectURL(S.recordUrl);S.recordUrl=null;}S.recorder=null;S.audioChunks=[];S.recordBlob=null;S.recordStartedAt=0;S.recordElapsed=0;const a=$('cacRecAudio');a.pause();a.removeAttribute('src');a.style.display='none';$('cacRecTime').textContent='00:00';$('cacRecLabel').textContent='Gravando áudio...';$('cacRecDot').style.display='inline-block';$('cacRecDot').classList.add('pulse');$('cacRecPause').style.display='inline-flex';$('cacRecPause').textContent='⏸';$('cacRecStop').style.display='inline-flex';$('cacRecSend').style.display='none';$('cacRecorder').classList.remove('open');$('cacComposeRow').style.display='flex';}
async function startRecording(){if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder){toast('Este navegador não disponibiliza gravação de áudio.',4000);return;}resetRecorder();showRecorder();try{S.recordStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const mime=recorderMime();S.audioChunks=[];S.recorder=mime?new MediaRecorder(S.recordStream,{mimeType:mime}):new MediaRecorder(S.recordStream);S.recordStartedAt=Date.now();S.recordElapsed=0;S.recorder.ondataavailable=e=>{if(e.data&&e.data.size)S.audioChunks.push(e.data);};S.recorder.onstop=()=>{if(S.recordTimer){clearInterval(S.recordTimer);S.recordTimer=null;}if(S.recordStartedAt){S.recordElapsed+=(Date.now()-S.recordStartedAt)/1000;S.recordStartedAt=0;}if(S.recordStream){S.recordStream.getTracks().forEach(t=>t.stop());S.recordStream=null;}if(S.recordCancelled){S.recordCancelled=false;resetRecorder();return;}const type=S.recorder?.mimeType||mime||'audio/webm';S.recordBlob=new Blob(S.audioChunks,{type});S.recordUrl=URL.createObjectURL(S.recordBlob);const a=$('cacRecAudio');a.src=S.recordUrl;a.style.display='block';$('cacRecDot').style.display='none';$('cacRecLabel').textContent='Prévia do áudio';$('cacRecPause').style.display='none';$('cacRecStop').style.display='none';$('cacRecSend').style.display='inline-flex';updateRecTimer();};S.recorder.start(250);S.recordTimer=setInterval(updateRecTimer,250);updateRecTimer();}catch(e){resetRecorder();toast('Não foi possível acessar o microfone. Verifique a permissão do navegador.',4500);}}
function pauseRecording(){if(!S.recorder)return;if(S.recorder.state==='recording'){S.recorder.pause();S.recordElapsed+=(Date.now()-S.recordStartedAt)/1000;S.recordStartedAt=0;$('cacRecPause').textContent='▶';$('cacRecLabel').textContent='Gravação pausada';$('cacRecDot').classList.remove('pulse');}else if(S.recorder.state==='paused'){S.recorder.resume();S.recordStartedAt=Date.now();$('cacRecPause').textContent='⏸';$('cacRecLabel').textContent='Gravando áudio...';$('cacRecDot').classList.add('pulse');}}
function stopRecording(){if(S.recorder&&(S.recorder.state==='recording'||S.recorder.state==='paused'))S.recorder.stop();}
function cancelRecording(){S.recordCancelled=true;if(S.recorder&&(S.recorder.state==='recording'||S.recorder.state==='paused'))S.recorder.stop();else resetRecorder();}
async function sendRecordedAudio(){if(!S.recordBlob)return;const mime=S.recordBlob.type||'audio/webm';const ext=mime.includes('ogg')?'ogg':(mime.includes('mp4')?'m4a':'webm');const file=new File([S.recordBlob],'audio-'+Date.now()+'.'+ext,{type:mime});$('cacRecSend').disabled=true;try{if(await sendFile(file,true,''))resetRecorder();}finally{if($('cacRecSend'))$('cacRecSend').disabled=false;}}
async function sendContact(){if(!S.conversation)return;const data={conversation_id:S.conversation.id,full_name:$('cacContactName').value.trim(),phone:$('cacContactPhone').value.trim(),organization:$('cacContactOrg').value.trim(),email:$('cacContactEmail').value.trim(),quoted_id:S.quote?S.quote.id:''};$('cacContactSend').disabled=true;try{await request(U.sendContact,{method:'POST',body:formBody(data)});$('cacContactModal').classList.remove('open');['cacContactName','cacContactPhone','cacContactOrg','cacContactEmail'].forEach(id=>$(id).value='');cancelQuote();await poll();S.listSignature='';}catch(e){toast(e.message,4500);}finally{$('cacContactSend').disabled=false;}}
async function performSync(){const b=$('cacSync');if(b)b.disabled=true;try{const r=await request(U.sync,{method:'POST',body:formBody({})});S.listSignature='';toast('<?php echo addslashes(_l('connect_api_chat_sync_done')); ?> '+(r.count||0));await loadList(false,false);}catch(e){toast(e.message,4500);}finally{if(b)b.disabled=false;}}
function openMessageSearch(){if(!S.conversation)return;$('cacInChatSearch').classList.add('open');$('cacMessageSearch').focus();}
function closeMessageSearch(){$('cacInChatSearch').classList.remove('open');$('cacMessageSearch').value='';$('cacMessageSearchCount').textContent='';S.messageSearchResults=[];S.messageSearchIndex=-1;}
async function runMessageSearch(){if(!S.conversation)return;const term=$('cacMessageSearch').value.trim();if(!term){S.messageSearchResults=[];S.messageSearchIndex=-1;$('cacMessageSearchCount').textContent='';return;}try{const r=await request(U.searchMessages+'?conversation_id='+S.conversation.id+'&q='+encodeURIComponent(term));S.messageSearchResults=r.results||[];S.messageSearchIndex=S.messageSearchResults.length?S.messageSearchResults.length-1:-1;updateMessageSearchCount();if(S.messageSearchIndex>=0)await goMessageSearchResult(S.messageSearchIndex);}catch(e){toast(e.message,3500);}}
function updateMessageSearchCount(){const n=S.messageSearchResults.length;$('cacMessageSearchCount').textContent=n?(S.messageSearchIndex+1)+' / '+n:'0 / 0';}
async function goMessageSearchResult(index){const n=S.messageSearchResults.length;if(!n||!S.conversation)return;index=(index+n)%n;S.messageSearchIndex=index;updateMessageSearchCount();await openChat(S.conversation.id,parseInt(S.messageSearchResults[index].id)||0);}
async function changeConversationStatus(action){if(!S.conversation)return;const close=action==='close';if(close&&!confirm('Encerrar este atendimento? O histórico será preservado. Uma nova mensagem recebida criará outro atendimento.'))return;try{const r=await request(U.conversationStatus,{method:'POST',body:formBody({conversation_id:S.conversation.id,action:action})});S.conversation.status=r.status||S.conversation.status;if(r.ticket){S.conversation.current_ticket_id=r.ticket.id;S.conversation.current_ticket_number=r.ticket.ticket_number;S.conversation.current_ticket_status=r.ticket.status;S.conversation.current_ticket_is_new=r.ticket.is_new;}updateActiveConversationMeta(S.conversation);updateConversationState(S.conversation);if(close){S.scope='closed';}else{S.scope=S.conversation.assigned_staff_id?'mine':'unassigned';}qa('.cac-tab').forEach(b=>b.classList.toggle('active',b.dataset.scope===S.scope));S.listSignature='';await loadList(false,false);toast(close?'<?php echo addslashes(_l('connect_api_chat_conversation_closed')); ?>':'<?php echo addslashes(_l('connect_api_chat_conversation_reopened')); ?>');}catch(e){toast(e.message,4000);}}
function openDetails(){$('cacDetails').classList.add('open');} function closeDetails(){$('cacDetails').classList.remove('open');}
qa('.cac-tab').forEach(b=>b.onclick=()=>setScope(b.dataset.scope));
let searchTimer;$('cacSearch').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{S.search=e.target.value;loadList(false);},250)};$('cacSync').onclick=performSync;
$('cacSearchConversation').onclick=openMessageSearch;$('cacSearchClose').onclick=closeMessageSearch;$('cacSearchPrev').onclick=()=>goMessageSearchResult(S.messageSearchIndex-1);$('cacSearchNext').onclick=()=>goMessageSearchResult(S.messageSearchIndex+1);$('cacMessageSearch').oninput=()=>{clearTimeout(S.messageSearchTimer);S.messageSearchTimer=setTimeout(runMessageSearch,350);};$('cacMessageSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();if(e.shiftKey)goMessageSearchResult(S.messageSearchIndex-1);else goMessageSearchResult(S.messageSearchIndex+1);}else if(e.key==='Escape')closeMessageSearch();};
